root.querySelector('.cement-list').innerHTML=rows.length?`<div class="table-scroll"><table><thead><tr>${(kind==='granel'?['Data','Empresa','Pedido sistema','Fornecedor','Pedido/contrato','Quantidade','Cimento','Transportador','NF','Status','Ações']:['Data','Entrega','Produto','Quantidade SC','Cidade','NF','OC','Freteiro','OC Freteiro','Valor frete','Status','Ações']).map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>kind==='granel'?`<tr><td>${day(r.scheduledDate)}</td><td>${esc(r.company)}</td><td>${esc(r.systemOrder)}</td><td>${esc(r.supplier)}</td><td>${esc(r.supplierOrder||'—')}</td><td>${esc(r.orderQuantity||'—')}</td><td>${esc(r.cementDescription||'—')}</td><td>${esc(r.carrier)}</td><td>${esc(r.invoice||'—')}</td><td><select class="load-status ${statusClass(r.status)}" data-load-status="${r.id}">${opts(statuses,r.status)}</select></td><td><button data-edit="${r.id}">Editar</button><details><summary>Histórico</summary><ol class="load-timeline">${r.history.filter(h=>h.changes?.status).map(h=>`<li><span class="load-status ${statusClass(h.changes.status.after)}">${esc(h.changes.status.after)}</span><time datetime="${esc(h.at)}">${esc(new Date(h.at).toLocaleString('pt-BR'))}</time></li>`).join('')}</ol></details></td></tr>`:`<tr><td>${day(r.scheduledDate)}</td><td>${esc(r.company)}</td><td>${esc(r.bagProduct)}</td><td>${esc(r.bagQuantity)}</td><td>${esc(r.deliveryCity)}</td><td>${esc(r.invoice||'—')}</td><td>${esc(r.purchaseOrder)}</td><td>${esc(r.carrier)}</td><td>${esc(r.freightOrder||'—')}</td><td>${esc(r.freightValue||'—')}</td><td><select class="load-status ${statusClass(r.status)}" data-load-status="${r.id}">${opts(statuses,r.status)}</select></td><td><button data-edit="${r.id}">Editar</button><details><summary>Histórico</summary><ol class="load-timeline">${r.history.filter(h=>h.changes?.status).map(h=>`<li><span class="load-status ${statusClass(h.changes.status.after)}">${esc(h.changes.status.after)}</span><time datetime="${esc(h.at)}">${esc(new Date(h.at).toLocaleString('pt-BR'))}</time></li>`).join('')}</ol></details></td></tr>`).join('')}</tbody></table></div>`:'<p class="empty-state">Nenhuma carga encontrada. Cadastre o primeiro agendamento acima.</p>';
root.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const r=loads.find(r=>r.id===b.dataset.edit),form=root.querySelector('form');for(const [k,v] of Object.entries(r))if(form.elements.namedItem(k))form.elements.namedItem(k).value=v;if(kind==='ensacado')root._setBagItems(bagItems(r));form.dataset.id=r.id;form.dataset.version=r.version;form.elements.status.disabled=false;form.elements.status.className='load-status '+statusClass(r.status);root.querySelector('[data-cancel]').hidden=false;root.querySelector('.cement-form-panel h3').textContent='Editar carga · pedido '+r.systemOrder;root.querySelector('.cement-message').textContent='';root.querySelector('[data-tab="list"]').click();form.scrollIntoView({behavior:'smooth'});});
root.querySelectorAll('[data-load-status]').forEach(select=>select.onchange=async()=>{const r=loads.find(r=>r.id===select.dataset.loadStatus),message=root.querySelector('.cement-message');select.disabled=true;try{await save({...r,status:select.value});message.textContent='Status atualizado e registrado no histórico.';}catch(e){select.value=r.status;select.disabled=false;message.textContent=e.message;}});
